selection.candidate_query:
SELECT ?company (MAX(?count) AS ?employees) WHERE {
  VALUES ?type { wd:Q4830453 wd:Q783794 wd:Q891723 wd:Q6881511 wd:Q167037 wd:Q726870 wd:Q18127 wd:Q2085381 wd:Q134161 }
  ?company wdt:P31 ?type; wdt:P1128 ?count. FILTER(?count > 0)
  FILTER NOT EXISTS { ?company wdt:P576 ?dissolved }
} GROUP BY ?company ORDER BY DESC(?employees) LIMIT 7000
